      integer :: slot_
      slot_ = thread_slot()   ! the work arrays of this thread in the pools of src/device/micro_pool.f90
      debug_flag = .false.
      if(debug_flag) then
      endif
      no_micro = .true.
      dtsave = dt
      odt = 1./dt
      odts = 1./dtsave
      iexfrq = 1
      do k = kts, kte
         tten(k) = 0.
         qvten(k) = 0.
         qcten(k) = 0.
         qiten(k) = 0.
         qrten(k) = 0.
         qsten(k) = 0.
         qgten(k) = 0.
         niten(k) = 0.
         nrten(k) = 0.
         ncten(k) = 0.
         pool_pr(slot_,k,1) = 0.
         pool_pr(slot_,k,2) = 0.
         pool_pd(slot_,k,1) = 0.
         pool_pd(slot_,k,2) = 0.
         pool_pd(slot_,k,3) = 0.
         pool_pd(slot_,k,4) = 0.
      enddo
! Reference module_mp_thompson.F:1623-1764
      do k = kts, kte
         rainprod(k) = 0.
         evapprod(k) = 0.
      enddo
      do k = kts, kte
         pool_pr(slot_,k,11) = 0.
         pool_pr(slot_,k,10) = 0.
         smo2(k) = 0.
         smob(k) = 0.
         pool_pr(slot_,k,12) = 0.
         pool_pr(slot_,k,13) = 0.
         pool_pr(slot_,k,14) = 0.
         pool_pr(slot_,k,15) = 0.
         mvd_r(k) = 0.
         mvd_c(k) = 0.
      enddo
      do k = kts, kte
         temp(k) = t1d(k)
         qv(k) = MAX(1.E-10, qv1d(k))
         pres(k) = p1d(k)
         rho(k) = 0.622*pres(k)/(R*temp(k)*(qv(k)+0.622))
         nwfa(k) = MAX(11.1E6, MIN(9999.E6, nwfa1d(k)*rho(k)))
         pool_pr(slot_,k,3) = MAX(naIN1*0.01, MIN(9999.E6, nifa1d(k)*rho(k)))
         if (qc1d(k) .gt. R1) then
            no_micro = .false.
            rc(k) = qc1d(k)*rho(k)
            nc(k) = MAX(2., MIN(nc1d(k)*rho(k), Nt_c_max))
            pool_pl(slot_,k,2) = .true.
            nu_c = MIN(15, NINT(1000.E6/nc(k)) + 2)
            lamc = (nc(k)*am_r*ccg(2,nu_c)*ocg1(nu_c)/rc(k))**obmr
            xDc = (bm_r + nu_c + 1.) / lamc
            if (xDc.lt. D0c) then
             lamc = cce(2,nu_c)/D0c
            elseif (xDc.gt. D0r*2.) then
             lamc = cce(2,nu_c)/(D0r*2.)
            endif
            nc(k) = MIN( DBLE(Nt_c_max), ccg(1,nu_c)*ocg2(nu_c)*rc(k)   &
                  / am_r*lamc**bm_r)
