               mvd_r(k) = 1.0E-3
               lamr = (3.0 + mu_r + 0.672) / mvd_r(k)
               nr(k) = crg(2)*org3*rr(k)*lamr**bm_r / am_r
            endif
            pool_pl(slot_,k,4) = .true.
            lamr = (am_r*crg(3)*org2*nr(k)/rr(k))**obmr
            mvd_r(k) = (3.0 + mu_r + 0.672) / lamr
            if (mvd_r(k) .gt. 2.5E-3) then
               mvd_r(k) = 2.5E-3
               lamr = (3.0 + mu_r + 0.672) / mvd_r(k)
               nr(k) = crg(2)*org3*rr(k)*lamr**bm_r / am_r
            elseif (mvd_r(k) .lt. D0r*0.75) then
               mvd_r(k) = D0r*0.75
               lamr = (3.0 + mu_r + 0.672) / mvd_r(k)
               nr(k) = crg(2)*org3*rr(k)*lamr**bm_r / am_r
            endif
      else
            qr1d(k) = 0.0
            nr1d(k) = 0.0
            rr(k) = R1
            nr(k) = R2
            pool_pl(slot_,k,4) = .false.
         endif
         if (qs1d(k) .gt. R1) then
            no_micro = .false.
            rs(k) = qs1d(k)*rho(k)
            pool_pl(slot_,k,5) = .true.
      else
            qs1d(k) = 0.0
            rs(k) = R1
            pool_pl(slot_,k,5) = .false.
         endif
         if (qg1d(k) .gt. R1) then
            no_micro = .false.
            rg(k) = qg1d(k)*rho(k)
            pool_pl(slot_,k,6) = .true.
      else
            qg1d(k) = 0.0
            rg(k) = R1
            pool_pl(slot_,k,6) = .false.
         endif
      enddo
! Reference module_mp_thompson.F:1765-1818
      do k = kts, kte
         tempc = temp(k) - 273.15
         rhof(k) = SQRT(RHO_NOT/rho(k))
         rhof2(k) = SQRT(rhof(k))
         qvs(k) = rslf_dev(pres(k), temp(k))
         pool_pr(slot_,k,5) = MAX(0.0, rslf_dev(pres(k), 273.15)-qv(k))
         if (tempc .le. 0.0) then
          pool_pr(slot_,k,4) = rsif_dev(pres(k), temp(k))
      else
          pool_pr(slot_,k,4) = qvs(k)
