          pool_pr(slot_,k,1) = pool_pr(slot_,k,1) &
                    + ( lsub*pool_pr(slot_,k,39)*(pri_inu + pri_ide &
                                     + prs_ide + prs_sde &
                                     + prg_gde + pri_iha) &
                     + lfus2*pool_pr(slot_,k,39)*(pri_wfz + pri_rfz &
                                     + prg_rfz + prs_scw &
                                     + prg_scw + prg_gcw &
                                     + prg_rcs + prs_rcs &
                                     + prr_rci + prg_rcg) &
                       )*orho * (1-IFDRY)
      else
          pool_pr(slot_,k,1) = pool_pr(slot_,k,1) &
                    + ( lfus*pool_pr(slot_,k,39)*(-prr_sml - prr_gml &
                                     - prr_rcg - prr_rcs) &
                      + lsub*pool_pr(slot_,k,39)*(prs_sde + prg_gde) &
                       )*orho * (1-IFDRY)
         endif
! what the rain evaporation and the production diagnostics need of this level's rates (module_mp_thompson.F:3171, 3213-3218)
         pool_pl(slot_,k,1) = prr_gml.gt.0.0
         pool_pd(slot_,k,5) = min(zeroD0,prs_sde) + min(zeroD0,prg_gde)
         rainprod(k) = prr_wau + prr_rcw + prs_scw + &
                                    prg_scw + prs_iau + &
                                    prg_gcw + prs_sci + &
                                    pri_rci
      end subroutine mp_thompson_b1
      subroutine mp_thompson_b1u (pptrain, pptsnow, pptgraul, pptice, rainprod, evapprod, dt, ii, jj, Nt_c, slot_, kk)
