          pool_pr(slot_,k,26) = 0.622*pool_pr(slot_,k,14)/(R*pool_pr(slot_,k,13)*(pool_pr(slot_,k,15)+0.622))
          pool_pr(slot_,k,29) = rslf_dev(pool_pr(slot_,k,14), pool_pr(slot_,k,13))
          pool_pr(slot_,k,32) = pool_pr(slot_,k,15)/pool_pr(slot_,k,29) - 1.
         endif
! Reference module_mp_thompson.F:3132-3219
         if ( (pool_pr(slot_,k,32).lt. -eps) .and. pool_pl(slot_,k,4) &
                     .and. (.not.(pool_pd(slot_,k,1).gt. 0.)) ) then
          tempc = pool_pr(slot_,k,13) - 273.15
          otemp = 1./pool_pr(slot_,k,13)
          orho = 1./pool_pr(slot_,k,26)
          pool_pr(slot_,k,27) = SQRT(RHO_NOT*orho)
          pool_pr(slot_,k,28) = SQRT(pool_pr(slot_,k,27))
          pool_pr(slot_,k,34) = 2.11E-5*(pool_pr(slot_,k,13)/273.15)**1.94 * (101325./pool_pr(slot_,k,14))
          if (tempc .ge. 0.0) then
             pool_pr(slot_,k,35) = (1.718+0.0049*tempc)*1.0E-5
      else
             pool_pr(slot_,k,35) = (1.718+0.0049*tempc-1.2E-5*tempc*tempc)*1.0E-5
          endif
          pool_pr(slot_,k,36) = SQRT(pool_pr(slot_,k,26)/pool_pr(slot_,k,35))
          pool_pr(slot_,k,38) = lvap0 + (2106.0 - 4218.0)*tempc
          pool_pr(slot_,k,37) = (5.69 + 0.0168*tempc)*1.0E-5 * 418.936
          pool_pr(slot_,k,39) = 1./(Cp*(1.+0.887*pool_pr(slot_,k,15)))
          rvs = pool_pr(slot_,k,26)*pool_pr(slot_,k,29)
          rvs_p = rvs*otemp*(pool_pr(slot_,k,38)*otemp*oRv - 1.)
          rvs_pp = rvs * ( otemp*(pool_pr(slot_,k,38)*otemp*oRv - 1.) &
                          *otemp*(pool_pr(slot_,k,38)*otemp*oRv - 1.) &
                          + (-2.*pool_pr(slot_,k,38)*otemp*otemp*otemp*oRv) &
                          + otemp*otemp)
          gamsc = pool_pr(slot_,k,38)*pool_pr(slot_,k,34)/pool_pr(slot_,k,37) * rvs_p
          alphsc = 0.5*(gamsc/(1.+gamsc))*(gamsc/(1.+gamsc)) &
                     * rvs_pp/rvs_p * rvs/rvs_p
          alphsc = MAX(1.E-9, alphsc)
          xsat   = MIN(-1.E-9, pool_pr(slot_,k,32))
          t1_evap = 2.*PI*( 1.0 - alphsc*xsat  &
                 + 2.*alphsc*alphsc*xsat*xsat  &
                 - 5.*alphsc*alphsc*alphsc*xsat*xsat*xsat ) &
                 / (1.+gamsc)
          lamr = 1./pool_pd(slot_,k,6)
          if (pool_pr(slot_,k,15)/pool_pr(slot_,k,29) .lt. 0.95 .AND. pool_pr(slot_,k,18)*orho.le.1.E-8) then
          pool_pd(slot_,k,3) = pool_pr(slot_,k,18)*orho*odts
      else
          pool_pd(slot_,k,3) = t1_evap*pool_pr(slot_,k,34)*(-pool_pr(slot_,k,32))*pool_pd(slot_,k,8)*rvs &
              * (t1_qr_ev*pool_pd(slot_,k,6)**cre(10) &
              + t2_qr_ev*pool_pr(slot_,k,36)*pool_pr(slot_,k,28)*((lamr+0.5*fv_r)**(-cre(11))))
          rate_max = MIN((pool_pr(slot_,k,18)*orho*odts), (pool_pr(slot_,k,29)-pool_pr(slot_,k,15))*odts)
          pool_pd(slot_,k,3) = MIN(DBLE(rate_max), pool_pd(slot_,k,3)*orho)
          IF (pool_pl(slot_,k,1)) THEN
             eva_factor = MIN(1.0, 0.01+(0.99-0.01)*(tempc/20.0))
             pool_pd(slot_,k,3) = pool_pd(slot_,k,3)*eva_factor
          ENDIF
          endif
          pool_pd(slot_,k,4) = MIN(DBLE(pool_pr(slot_,k,22)*0.99*orho*odts),                  &   ! RAIN2M
                       pool_pd(slot_,k,3) * pool_pr(slot_,k,22)/pool_pr(slot_,k,18))
          pool_pr(slot_,k,5) = pool_pr(slot_,k,5) - pool_pd(slot_,k,3)
          pool_pr(slot_,k,2) = pool_pr(slot_,k,2) + pool_pd(slot_,k,3)
          pool_pr(slot_,k,9) = pool_pr(slot_,k,9) - pool_pd(slot_,k,4)
          pool_pr(slot_,k,11) = pool_pr(slot_,k,11) + pool_pd(slot_,k,4)
          pool_pr(slot_,k,1) = pool_pr(slot_,k,1) - pool_pr(slot_,k,38)*pool_pr(slot_,k,39)*pool_pd(slot_,k,3)*(1-IFDRY)
          pool_pr(slot_,k,18) = MAX(R1, (pool_mc(slot_,k,4) + DT*pool_pr(slot_,k,5))*pool_pr(slot_,k,26))
          pool_pr(slot_,k,15) = MAX(1.E-10, pool_mc(slot_,k,1) + DT*pool_pr(slot_,k,2))
          pool_pr(slot_,k,22) = MAX(R2, (pool_mc(slot_,k,8) + DT*pool_pr(slot_,k,9))*pool_pr(slot_,k,26))
          pool_pr(slot_,k,13) = pool_mc(slot_,k,12) + DT*pool_pr(slot_,k,1)
          pool_pr(slot_,k,26) = 0.622*pool_pr(slot_,k,14)/(R*pool_pr(slot_,k,13)*(pool_pr(slot_,k,15)+0.622))
         endif
         evapprod(k) = pool_pd(slot_,k,3) - pool_pd(slot_,k,5)
      end subroutine mp_thompson_b2
      subroutine mp_thompson_b3 (pptrain, pptsnow, pptgraul, pptice, rainprod, evapprod, dt, ii, jj, Nt_c, slot_, kk)
      use micro_pool, only: pool_pd, pool_pl, pool_pr
      use lean_warp, only: thread_slot
 use config, only: max_levels
 !$acc routine seq
      use micro_pool, only: pool_mc
      implicit none
      integer, intent(in) :: slot_, kk
      INTEGER, PARAMETER :: kts=1
      INTEGER, INTENT(IN):: ii, jj
      REAL, INTENT(IN) :: Nt_c
      REAL, INTENT(INOUT):: pptrain, pptsnow, pptgraul, pptice
      REAL, INTENT(IN):: dt
      REAL, DIMENSION(kts:kte), INTENT(INOUT):: &
                          rainprod, evapprod
! the process rates of one level are scalars: rates, limits and tendencies run in one level loop (lean)
      DOUBLE PRECISION:: pnc_wau, pnc_rcw, pnc_scw, pnc_gcw, pna_rca, pna_sca, pna_gca, pnd_rcd, &
            pnd_scd, pnd_gcd, prr_wau, prr_rcw, prr_rcs, prr_rcg, prr_sml, prr_gml, prr_rci, &
            pnr_wau, pnr_rcs, pnr_rcg, pnr_rci, pnr_sml, pnr_gml, pnr_rcr, pnr_rfz, pri_inu, &
            pni_inu, pri_ihm, pni_ihm, pri_wfz, pni_wfz, pri_rfz, pni_rfz, pri_ide, pni_ide, &
            pri_rci, pni_rci, pni_sci, pni_iau, pri_iha, pni_iha, prs_iau, prs_sci, prs_rcs, &
            prs_scw, prs_sde, prs_ihm, prs_ide, prg_scw, prg_rfz, prg_gde, prg_gcw, prg_rci, &
            prg_rcs, prg_rcg, prg_ihm
      DOUBLE PRECISION, PARAMETER:: zeroD0 = 0.0d0
      REAL, DIMENSION(kts:max_levels) :: satw, sati
      REAL, DIMENSION(kts:max_levels) :: sed_r, sed_s, sed_g, sed_i, sed_n, sed_c
      REAL:: rgvm, delta_tp, orho, lfus2
      REAL, DIMENSION(5):: onstep
      DOUBLE PRECISION:: N0_exp, N0_min, lam_exp, lamc, lamr, lamg
      DOUBLE PRECISION:: lami, ilami, ilamc
      REAL:: xDc, Dc_b, Dc_g, xDi, xDr, xDs, xDg, Ds_m, Dg_m
      DOUBLE PRECISION:: Dr_star, Dc_star
      REAL:: zeta1, zeta, taud, tau
      REAL:: stoke_r, stoke_s, stoke_g, stoke_i
      REAL:: vti, vtr, vts, vtg, vtc
      REAL, DIMENSION(kts:max_levels+1) :: vtik, vtnik, vtrk, vtnrk, vtsk, vtgk, vtck, vtnck
      REAL:: Mrat, ils1, ils2, t1_vts, t2_vts, t3_vts, t4_vts, C_snow
      REAL:: a_, b_, loga_, A1, A2, tf
      REAL:: tempc, tc0, r_mvd1, r_mvd2, xkrat
      REAL:: xnc, xri, xni, xmi, oxmi, xrc, xrr, xnr
      REAL:: xsat, rate_max, sump, ratio
      REAL:: clap, fcd, dfcd
      REAL:: otemp, rvs, rvs_p, rvs_pp, gamsc, alphsc, t1_evap, t1_subl
      REAL:: r_frac, g_frac
      REAL:: Ef_rw, Ef_sw, Ef_gw, Ef_rr
      REAL:: Ef_ra, Ef_sa, Ef_ga
      REAL:: dtsave, odts, odt, odzq, hgt_agl, SR
      REAL:: xslw1, ygra1, zans1, eva_factor
      INTEGER:: i, k, k2, n, nn, nstep, k_0, kbot, IT, iexfrq
      INTEGER, DIMENSION(5):: ksed1
      INTEGER:: nir, nis, nig, nii, nic, niin
      INTEGER:: idx_tc, idx_t, idx_s, idx_g1, idx_g, idx_r1, idx_r,     &
                idx_i1, idx_i, idx_c, idx, idx_d, idx_n, idx_in
      LOGICAL:: melti, no_micro
      LOGICAL:: debug_flag
      character(len=256):: mp_debug
      INTEGER:: nu_c
      LOGICAL, DIMENSION(kts:max_levels) :: L_nifa, L_nwfa
      REAL:: tem
! Reference module_mp_thompson.F:1513-1622
      dtsave = dt
      odt = 1./dt
      odts = 1./dtsave
      k = kk
         xri = MAX(0.0, pool_mc(slot_,k,3) + pool_pr(slot_,k,4)*DT)
         if ( (pool_pr(slot_,k,13).gt. T_0) .and. (xri.gt. 0.0) ) then
          pool_pr(slot_,k,3) = pool_pr(slot_,k,3) + xri*odt
          pool_pr(slot_,k,10) = pool_pr(slot_,k,10) + pool_mc(slot_,k,7)*odt
          pool_pr(slot_,k,4) = pool_pr(slot_,k,4) - xri*odt
          pool_pr(slot_,k,8) = -pool_mc(slot_,k,7)*odt
          pool_pr(slot_,k,1) = pool_pr(slot_,k,1) - lfus*pool_pr(slot_,k,39)*xri*odt*(1-IFDRY)
         endif
         xrc = MAX(0.0, pool_mc(slot_,k,2) + pool_pr(slot_,k,3)*DT)
         if ( (pool_pr(slot_,k,13).lt. HGFR) .and. (xrc.gt. 0.0) ) then
          lfus2 = lsub - pool_pr(slot_,k,38)
          xnc = pool_mc(slot_,k,9) + pool_pr(slot_,k,10)*DT
          pool_pr(slot_,k,4) = pool_pr(slot_,k,4) + xrc*odt
          pool_pr(slot_,k,8) = pool_pr(slot_,k,8) + xnc*odt
          pool_pr(slot_,k,3) = pool_pr(slot_,k,3) - xrc*odt
          pool_pr(slot_,k,10) = pool_pr(slot_,k,10) - xnc*odt
          pool_pr(slot_,k,1) = pool_pr(slot_,k,1) + lfus2*pool_pr(slot_,k,39)*xrc*odt*(1-IFDRY)
         endif
! Reference module_mp_thompson.F:3573-3641
         pool_mc(slot_,k,12)  = pool_mc(slot_,k,12) + pool_pr(slot_,k,1)*DT
         pool_mc(slot_,k,1) = MAX(1.E-10, pool_mc(slot_,k,1) + pool_pr(slot_,k,2)*DT)
         pool_mc(slot_,k,2) = pool_mc(slot_,k,2) + pool_pr(slot_,k,3)*DT
         pool_mc(slot_,k,9) = MAX(2./pool_pr(slot_,k,26), MIN(pool_mc(slot_,k,9) + pool_pr(slot_,k,10)*DT, Nt_c_max))
         pool_mc(slot_,k,10) = MAX(11.1E6, MIN(9999.E6,                           &
                       (pool_mc(slot_,k,10)+pool_pr(slot_,k,11)*DT)))
         pool_mc(slot_,k,11) = MAX(naIN1*0.01, MIN(9999.E6,                       &
                       (pool_mc(slot_,k,11)+pool_pr(slot_,k,12)*DT)))
         if (pool_mc(slot_,k,2) .le. R1) then
           pool_mc(slot_,k,2) = 0.0
           pool_mc(slot_,k,9) = 0.0
      else
           nu_c = MIN(15, NINT(1000.E6/(pool_mc(slot_,k,9)*pool_pr(slot_,k,26))) + 2)
           lamc = (am_r*ccg(2,nu_c)*ocg1(nu_c)*pool_mc(slot_,k,9)/pool_mc(slot_,k,2))**obmr
           xDc = (bm_r + nu_c + 1.) / lamc
           if (xDc.lt. D0c) then
            lamc = cce(2,nu_c)/D0c
           elseif (xDc.gt. D0r*2.) then
            lamc = cce(2,nu_c)/(D0r*2.)
           endif
           pool_mc(slot_,k,9) = MIN(ccg(1,nu_c)*ocg2(nu_c)*pool_mc(slot_,k,2)/am_r*lamc**bm_r,&
                         DBLE(Nt_c_max)/pool_pr(slot_,k,26))
         endif
         pool_mc(slot_,k,3) = pool_mc(slot_,k,3) + pool_pr(slot_,k,4)*DT
         pool_mc(slot_,k,7) = MAX(R2/pool_pr(slot_,k,26), pool_mc(slot_,k,7) + pool_pr(slot_,k,8)*DT)
         if (pool_mc(slot_,k,3) .le. R1) then
           pool_mc(slot_,k,3) = 0.0
           pool_mc(slot_,k,7) = 0.0
      else
           lami = (am_i*cig(2)*oig1*pool_mc(slot_,k,7)/pool_mc(slot_,k,3))**obmi
           ilami = 1./lami
           xDi = (bm_i + mu_i + 1.) * ilami
           if (xDi.lt. 5.E-6) then
            lami = cie(2)/5.E-6
           elseif (xDi.gt. 300.E-6) then
            lami = cie(2)/300.E-6
           endif
           pool_mc(slot_,k,7) = MIN(cig(1)*oig2*pool_mc(slot_,k,3)/am_i*lami**bm_i,           &
                         9999.D3/pool_pr(slot_,k,26))
         endif
         pool_mc(slot_,k,4) = pool_mc(slot_,k,4) + pool_pr(slot_,k,5)*DT
         pool_mc(slot_,k,8) = MAX(R2/pool_pr(slot_,k,26), pool_mc(slot_,k,8) + pool_pr(slot_,k,9)*DT)
         if (pool_mc(slot_,k,4) .le. R1) then
           pool_mc(slot_,k,4) = 0.0
           pool_mc(slot_,k,8) = 0.0
      else
           lamr = (am_r*crg(3)*org2*pool_mc(slot_,k,8)/pool_mc(slot_,k,4))**obmr
           pool_pr(slot_,k,41) = (3.0 + mu_r + 0.672) / lamr
           if (pool_pr(slot_,k,41) .gt. 2.5E-3) then
              pool_pr(slot_,k,41) = 2.5E-3
           elseif (pool_pr(slot_,k,41) .lt. D0r*0.75) then
              pool_pr(slot_,k,41) = D0r*0.75
           endif
           lamr = (3.0 + mu_r + 0.672) / pool_pr(slot_,k,41)
           pool_mc(slot_,k,8) = crg(2)*org3*pool_mc(slot_,k,4)*lamr**bm_r / am_r
         endif
         pool_mc(slot_,k,5) = pool_mc(slot_,k,5) + pool_pr(slot_,k,6)*DT
         if (pool_mc(slot_,k,5) .le. R1) pool_mc(slot_,k,5) = 0.0
         pool_mc(slot_,k,6) = pool_mc(slot_,k,6) + pool_pr(slot_,k,7)*DT
         if (pool_mc(slot_,k,6) .le. R1) pool_mc(slot_,k,6) = 0.0
      end subroutine mp_thompson_b3
      subroutine table_Efrw
      implicit none
      DOUBLE PRECISION:: vtr, stokes, reynolds, Ef_rw
      DOUBLE PRECISION:: p, yc0, F, G, H, z, K0, X
      INTEGER:: i, j
      do j = 1, nbc
      do i = 1, nbr
         Ef_rw = 0.0
         p = Dc(j)/Dr(i)
         if (Dr(i).lt.50.E-6 .or. Dc(j).lt.3.E-6) then
          t_Efrw(i,j) = 0.0
         elseif (p.gt.0.25) then
          X = Dc(j)*1.D6
          if (Dr(i) .lt. 75.e-6) then
             Ef_rw = 0.026794*X - 0.20604
          elseif (Dr(i) .lt. 125.e-6) then
             Ef_rw = -0.00066842*X*X + 0.061542*X - 0.37089
          elseif (Dr(i) .lt. 175.e-6) then
             Ef_rw = 4.091e-06*X*X*X*X - 0.00030908*X*X*X               &
                   + 0.0066237*X*X - 0.0013687*X - 0.073022
          elseif (Dr(i) .lt. 250.e-6) then
             Ef_rw = 9.6719e-5*X*X*X - 0.0068901*X*X + 0.17305*X        &
                   - 0.65988
          elseif (Dr(i) .lt. 350.e-6) then
             Ef_rw = 9.0488e-5*X*X*X - 0.006585*X*X + 0.16606*X         &
                   - 0.56125
          else
             Ef_rw = 0.00010721*X*X*X - 0.0072962*X*X + 0.1704*X        &
                   - 0.46929
          endif
         else
          vtr = -0.1021 + 4.932E3*Dr(i) - 0.9551E6*Dr(i)*Dr(i) &
              + 0.07934E9*Dr(i)*Dr(i)*Dr(i) &
              - 0.002362E12*Dr(i)*Dr(i)*Dr(i)*Dr(i)
          stokes = Dc(j)*Dc(j)*vtr*rho_w/(9.*1.718E-5*Dr(i))
          reynolds = 9.*stokes/(p*p*rho_w)
          F = DLOG(reynolds)
          G = -0.1007D0 - 0.358D0*F + 0.0261D0*F*F
          K0 = DEXP(G)
          z = DLOG(stokes/(K0+1.D-15))
          H = 0.1465D0 + 1.302D0*z - 0.607D0*z*z + 0.293D0*z*z*z
          yc0 = 2.0D0/PI * ATAN(H)
          Ef_rw = (yc0+p)*(yc0+p) / ((1.+p)*(1.+p))
         endif
         t_Efrw(i,j) = MAX(0.0, MIN(SNGL(Ef_rw), 0.95))
      enddo
      enddo
      end subroutine table_Efrw
      subroutine table_Efsw
      implicit none
      DOUBLE PRECISION:: Ds_m, vts, vtc, stokes, reynolds, Ef_sw
      DOUBLE PRECISION:: p, yc0, F, G, H, z, K0
      INTEGER:: i, j
      do j = 1, nbc
      vtc = 1.19D4 * (1.0D4*Dc(j)*Dc(j)*0.25D0)
      do i = 1, nbs
         vts = av_s*Ds(i)**bv_s * DEXP(-fv_s*Ds(i)) - vtc
         Ds_m = (am_s*Ds(i)**bm_s / am_r)**obmr
         p = Dc(j)/Ds_m
         if (p.gt.0.25 .or. Ds(i).lt.D0s .or. Dc(j).lt.6.E-6 &
               .or. vts.lt.1.E-3) then
          t_Efsw(i,j) = 0.0
         else
          stokes = Dc(j)*Dc(j)*vts*rho_w/(9.*1.718E-5*Ds_m)
          reynolds = 9.*stokes/(p*p*rho_w)
          F = DLOG(reynolds)
          G = -0.1007D0 - 0.358D0*F + 0.0261D0*F*F
          K0 = DEXP(G)
          z = DLOG(stokes/(K0+1.D-15))
          H = 0.1465D0 + 1.302D0*z - 0.607D0*z*z + 0.293D0*z*z*z
          yc0 = 2.0D0/PI * ATAN(H)
          Ef_sw = (yc0+p)*(yc0+p) / ((1.+p)*(1.+p))
          t_Efsw(i,j) = MAX(0.0, MIN(SNGL(Ef_sw), 0.95))
         endif
      enddo
      enddo
      end subroutine table_Efsw
      real function Eff_aero(D, Da, visc,rhoa,Temp,species)
      implicit none
      real:: D, Da, visc, rhoa, Temp
      character(LEN=1):: species
      real:: aval, Cc, diff, Re, Sc, St, St2, vt, Eff
      real, parameter:: boltzman = 1.3806503E-23
      real, parameter:: meanPath = 0.0256E-6
      vt = 1.
      if (species .eq. 'r') then
         vt = -0.1021 + 4.932E3*D - 0.9551E6*D*D                        &
              + 0.07934E9*D*D*D - 0.002362E12*D*D*D*D
      elseif (species .eq. 's') then
         vt = av_s*D**bv_s
      elseif (species .eq. 'g') then
         vt = av_g*D**bv_g
      endif
      Cc    = 1. + 2.*meanPath/Da *(1.257+0.4*exp(-0.55*Da/meanPath))
      diff  = boltzman*Temp*Cc/(3.*PI*visc*Da)
      Re    = 0.5*rhoa*D*vt/visc
      Sc    = visc/(rhoa*diff)
      St    = Da*Da*vt*1000./(9.*visc*D)
      aval  = 1.+LOG(1.+Re)
      St2   = (1.2 + 1./12.*aval)/(1.+aval)
      Eff = 4./(Re*Sc) * (1. + 0.4*SQRT(Re)*Sc**0.3333                  &
                             + 0.16*SQRT(Re)*SQRT(Sc))                  &
               + 4.*Da/D * (0.02 + Da/D*(1.+2.*SQRT(Re)))
      if (St.gt.St2) Eff = Eff  + ( (St-St2)/(St-St2+0.666667))**1.5
      Eff_aero = MAX(1.E-5, MIN(Eff, 1.0))
      end function Eff_aero
      subroutine table_dropEvap
      implicit none
      INTEGER:: i, j, k, n
      DOUBLE PRECISION, DIMENSION(nbc):: N_c, massc
      DOUBLE PRECISION:: summ, summ2, lamc, N0_c
      INTEGER:: nu_c
      do n = 1, nbc
         massc(n) = am_r*Dc(n)**bm_r
      enddo
      do k = 1, nbc
         nu_c = MIN(15, NINT(1000.E6/t_Nc(k)) + 2)
         do j = 1, ntb_c
            lamc = (t_Nc(k)*am_r* ccg(2,nu_c)*ocg1(nu_c) / r_c(j))**obmr
            N0_c = t_Nc(k)*ocg1(nu_c) * lamc**cce(1,nu_c)
            do i = 1, nbc
               N_c(i) = N0_c* Dc(i)**nu_c*EXP(-lamc*Dc(i))*dtc(i)
               summ = 0.
               summ2 = 0.
               do n = 1, i
                  summ = summ + massc(n)*N_c(n)
                  summ2 = summ2 + N_c(n)
               enddo
               tpc_wev(i,j,k) = summ
               tnc_wev(i,j,k) = summ2
            enddo
         enddo
      enddo
      end subroutine table_dropEvap
      subroutine calc_effectRad (t1d, p1d, qv1d, qc1d, nc1d, qi1d, ni1d, qs1d,   &
     &                re_qc1d, re_qi1d, re_qs1d, Nt_c)
 use config, only: max_levels
 !$acc routine seq
      IMPLICIT NONE
      REAL, INTENT(IN) :: Nt_c
      INTEGER, PARAMETER :: kts=1
      REAL, DIMENSION(kts:kte), INTENT(IN)::                            &
     &                    t1d, p1d, qv1d, qc1d, nc1d, qi1d, ni1d, qs1d
      REAL, DIMENSION(kts:kte), INTENT(INOUT):: re_qc1d, re_qi1d, re_qs1d
      INTEGER:: k
      REAL, DIMENSION(kts:max_levels) :: rho, rc, nc, ri, ni, rs
      REAL:: smo2, smob, smoc
      REAL:: tc0, loga_, a_, b_
      DOUBLE PRECISION:: lamc, lami
      LOGICAL:: has_qc, has_qi, has_qs
      INTEGER:: inu_c
      real, dimension(15), parameter:: g_ratio = (/24,60,120,210,336,   &
     &                504,720,990,1320,1716,2184,2730,3360,4080,4896/)
      has_qc = .false.
      has_qi = .false.
      has_qs = .false.
      do k = kts, kte
         rho(k) = 0.622*p1d(k)/(R*t1d(k)*(qv1d(k)+0.622))
         rc(k) = MAX(R1, qc1d(k)*rho(k))
         nc(k) = MAX(2., MIN(nc1d(k)*rho(k), Nt_c_max))
         nc(k) = Nt_c
         if (rc(k).gt.R1 .and. nc(k).gt.R2) has_qc = .true.
         ri(k) = MAX(R1, qi1d(k)*rho(k))
         ni(k) = MAX(R2, ni1d(k)*rho(k))
         if (ri(k).gt.R1 .and. ni(k).gt.R2) has_qi = .true.
         rs(k) = MAX(R1, qs1d(k)*rho(k))
         if (rs(k).gt.R1) has_qs = .true.
      enddo
      if (has_qc) then
      do k = kts, kte
         re_qc1d(k) = 2.49E-6
         if (rc(k).le.R1 .or. nc(k).le.R2) CYCLE
         if (nc(k).lt.100) then
            inu_c = 15
         elseif (nc(k).gt.1.E10) then
            inu_c = 2
         else
            inu_c = MIN(15, NINT(1000.E6/nc(k)) + 2)
         endif
         lamc = (nc(k)*am_r*g_ratio(inu_c)/rc(k))**obmr
         re_qc1d(k) = MAX(2.51E-6, MIN(SNGL(0.5D0 * DBLE(3.+inu_c)/lamc), 50.E-6))
      enddo
      endif
      if (has_qi) then
      do k = kts, kte
         re_qi1d(k) = 2.49E-6
         if (ri(k).le.R1 .or. ni(k).le.R2) CYCLE
         lami = (am_i*cig(2)*oig1*ni(k)/ri(k))**obmi
         re_qi1d(k) = MAX(2.51E-6, MIN(SNGL(0.5D0 * DBLE(3.+mu_i)/lami), 125.E-6))
      enddo
      endif
      if (has_qs) then
      do k = kts, kte
         re_qs1d(k) = 4.99E-6
         if (rs(k).le.R1) CYCLE
         tc0 = MIN(-0.1, t1d(k)-273.15)
         smob = rs(k)*oams
         if (bm_s.gt.(2.0-1.e-3) .and. bm_s.lt.(2.0+1.e-3)) then
            smo2 = smob
         else
            loga_ = sa(1) + sa(2)*tc0 + sa(3)*bm_s &
     &         + sa(4)*tc0*bm_s + sa(5)*tc0*tc0 &
     &         + sa(6)*bm_s*bm_s + sa(7)*tc0*tc0*bm_s &
     &         + sa(8)*tc0*bm_s*bm_s + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*bm_s*bm_s*bm_s
            a_ = 10.0**loga_
            b_ = sb(1) + sb(2)*tc0 + sb(3)*bm_s &
     &         + sb(4)*tc0*bm_s + sb(5)*tc0*tc0 &
     &         + sb(6)*bm_s*bm_s + sb(7)*tc0*tc0*bm_s &
     &         + sb(8)*tc0*bm_s*bm_s + sb(9)*tc0*tc0*tc0 &
     &         + sb(10)*bm_s*bm_s*bm_s
            smo2 = (smob/a_)**(1./b_)
         endif
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(1) &
     &         + sa(4)*tc0*cse(1) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(1)*cse(1) + sa(7)*tc0*tc0*cse(1) &
     &         + sa(8)*tc0*cse(1)*cse(1) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(1)*cse(1)*cse(1)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(1) + sb(4)*tc0*cse(1) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(1)*cse(1) &
     &        + sb(7)*tc0*tc0*cse(1) + sb(8)*tc0*cse(1)*cse(1) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(1)*cse(1)*cse(1)
         smoc = a_ * smo2**b_
         re_qs1d(k) = MAX(5.01E-6, MIN(0.5*(smoc/smob), 999.E-6))
      enddo
      endif
      end subroutine calc_effectRad
      subroutine calc_refl10cm (qv1d, qc1d, qr1d, nr1d, qs1d, qg1d,     &
                          t1d, p1d, dBZ, kts, kte, ii, jj)
      IMPLICIT NONE
      LOGICAL, PARAMETER:: iiwarm = .false.
      INTEGER, INTENT(IN):: kts, kte, ii, jj
      REAL, DIMENSION(kts:kte), INTENT(IN)::                            &
                          qv1d, qc1d, qr1d, nr1d, qs1d, qg1d, t1d, p1d
      REAL, DIMENSION(kts:kte), INTENT(INOUT):: dBZ
      REAL, DIMENSION(kts:kte):: temp, pres, qv, rho, rhof
      REAL, DIMENSION(kts:kte):: rc, rr, nr, rs, rg
      DOUBLE PRECISION, DIMENSION(kts:kte):: ilamr, ilamg, N0_r, N0_g
      REAL, DIMENSION(kts:kte):: mvd_r
      REAL, DIMENSION(kts:kte):: smob, smo2, smoc, smoz
      REAL:: oM3, M0, Mrat, slam1, slam2, xDs
      REAL:: ils1, ils2, t1_vts, t2_vts, t3_vts, t4_vts
      REAL:: vtr_dbz_wt, vts_dbz_wt, vtg_dbz_wt
      REAL, DIMENSION(kts:kte):: ze_rain, ze_snow, ze_graupel
      DOUBLE PRECISION:: N0_exp, N0_min, lam_exp, lamr, lamg
      REAL:: a_, b_, loga_, tc0
      DOUBLE PRECISION:: fmelt_s, fmelt_g
      INTEGER:: i, k, k_0, kbot, n
      LOGICAL:: melti
      LOGICAL, DIMENSION(kts:kte):: L_qr, L_qs, L_qg
      DOUBLE PRECISION:: cback, x, eta, f_d
      REAL:: xslw1, ygra1, zans1
      do k = kts, kte
         dBZ(k) = -35.0
      enddo
      do k = kts, kte
         temp(k) = t1d(k)
         qv(k) = MAX(1.E-10, qv1d(k))
         pres(k) = p1d(k)
         rho(k) = 0.622*pres(k)/(R*temp(k)*(qv(k)+0.622))
         rhof(k) = SQRT(RHO_NOT/rho(k))
         rc(k) = MAX(R1, qc1d(k)*rho(k))
         if (qr1d(k) .gt. R1) then
            rr(k) = qr1d(k)*rho(k)
            nr(k) = MAX(R2, nr1d(k)*rho(k))
            lamr = (am_r*crg(3)*org2*nr(k)/rr(k))**obmr
            ilamr(k) = 1./lamr
            N0_r(k) = nr(k)*org2*lamr**cre(2)
            mvd_r(k) = (3.0 + mu_r + 0.672) * ilamr(k)
            L_qr(k) = .true.
         else
            rr(k) = R1
            nr(k) = R1
            mvd_r(k) = 50.E-6
            L_qr(k) = .false.
         endif
         if (qs1d(k) .gt. R2) then
            rs(k) = qs1d(k)*rho(k)
            L_qs(k) = .true.
         else
            rs(k) = R1
            L_qs(k) = .false.
         endif
         if (qg1d(k) .gt. R2) then
            rg(k) = qg1d(k)*rho(k)
            L_qg(k) = .true.
         else
            rg(k) = R1
            L_qg(k) = .false.
         endif
      enddo
      do k = kts, kte
         smo2(k) = 0.
         smob(k) = 0.
         smoc(k) = 0.
         smoz(k) = 0.
      enddo
      if (ANY(L_qs .eqv. .true.)) then
      do k = kts, kte
         if (.not. L_qs(k)) CYCLE
         tc0 = MIN(-0.1, temp(k)-273.15)
         smob(k) = rs(k)*oams
         if (bm_s.gt.(2.0-1.e-3) .and. bm_s.lt.(2.0+1.e-3)) then
            smo2(k) = smob(k)
         else
            loga_ = sa(1) + sa(2)*tc0 + sa(3)*bm_s &
     &         + sa(4)*tc0*bm_s + sa(5)*tc0*tc0 &
     &         + sa(6)*bm_s*bm_s + sa(7)*tc0*tc0*bm_s &
     &         + sa(8)*tc0*bm_s*bm_s + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*bm_s*bm_s*bm_s
            a_ = 10.0**loga_
            b_ = sb(1) + sb(2)*tc0 + sb(3)*bm_s &
     &         + sb(4)*tc0*bm_s + sb(5)*tc0*tc0 &
     &         + sb(6)*bm_s*bm_s + sb(7)*tc0*tc0*bm_s &
     &         + sb(8)*tc0*bm_s*bm_s + sb(9)*tc0*tc0*tc0 &
     &         + sb(10)*bm_s*bm_s*bm_s
            smo2(k) = (smob(k)/a_)**(1./b_)
         endif
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(1) &
     &         + sa(4)*tc0*cse(1) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(1)*cse(1) + sa(7)*tc0*tc0*cse(1) &
     &         + sa(8)*tc0*cse(1)*cse(1) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(1)*cse(1)*cse(1)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(1) + sb(4)*tc0*cse(1) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(1)*cse(1) &
     &        + sb(7)*tc0*tc0*cse(1) + sb(8)*tc0*cse(1)*cse(1) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(1)*cse(1)*cse(1)
         smoc(k) = a_ * smo2(k)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(3) &
     &         + sa(4)*tc0*cse(3) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(3)*cse(3) + sa(7)*tc0*tc0*cse(3) &
     &         + sa(8)*tc0*cse(3)*cse(3) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(3)*cse(3)*cse(3)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(3) + sb(4)*tc0*cse(3) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(3)*cse(3) &
     &        + sb(7)*tc0*tc0*cse(3) + sb(8)*tc0*cse(3)*cse(3) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(3)*cse(3)*cse(3)
         smoz(k) = a_ * smo2(k)**b_
      enddo
      endif
      if (ANY(L_qg .eqv. .true.)) then
      N0_min = gonv_max
      k_0 = kts
      do k = kte, kts, -1
         if (temp(k).ge.270.65) k_0 = MAX(k_0, k)
      enddo
      do k = kte, kts, -1
         if (k.gt.k_0 .and. L_qr(k) .and. mvd_r(k).gt.100.E-6) then
            xslw1 = 4.01 + alog10(mvd_r(k))
         else
            xslw1 = 0.01
         endif
         ygra1 = 4.31 + alog10(max(5.E-5, rg(k)))
         zans1 = 3.1 + (100./(300.*xslw1*ygra1/(10./xslw1+1.+0.25*ygra1)+30.+10.*ygra1))
         N0_exp = 10.**(zans1)
         N0_exp = MAX(DBLE(gonv_min), MIN(N0_exp, DBLE(gonv_max)))
         N0_min = MIN(N0_exp, N0_min)
         N0_exp = N0_min
         lam_exp = (N0_exp*am_g*cgg(1)/rg(k))**oge1
         lamg = lam_exp * (cgg(3)*ogg2*ogg1)**obmg
         ilamg(k) = 1./lamg
         N0_g(k) = N0_exp/(cgg(2)*lam_exp) * lamg**cge(2)
      enddo
      endif
      melti = .false.
      k_0 = kts
      do k = kte-1, kts, -1
         if ( (temp(k).gt.273.15) .and. L_qr(k)                         &
     &                            .and. (L_qs(k+1).or.L_qg(k+1)) ) then
            k_0 = MAX(k+1, k_0)
            melti=.true.
            goto 195
         endif
      enddo
 195  continue
      do k = kts, kte
         ze_rain(k) = 1.e-22
         ze_snow(k) = 1.e-22
         ze_graupel(k) = 1.e-22
         if (L_qr(k)) ze_rain(k) = N0_r(k)*crg(4)*ilamr(k)**cre(4)
         if (L_qs(k)) ze_snow(k) = (0.176/0.93) * (6.0/PI)*(6.0/PI)     &
     &                           * (am_s/900.0)*(am_s/900.0)*smoz(k)
         if (L_qg(k)) ze_graupel(k) = (0.176/0.93) * (6.0/PI)*(6.0/PI)  &
     &                              * (am_g/900.0)*(am_g/900.0)         &
     &                              * N0_g(k)*cgg(4)*ilamg(k)**cge(4)
      enddo
      if (.not. iiwarm .and. melti .and. k_0.ge.2) then
       do k = k_0-1, kts, -1
          if (L_qs(k) .and. L_qs(k_0) ) then
           fmelt_s = MAX(0.05d0, MIN(1.0d0-rs(k)/rs(k_0), 0.99d0))
           eta = 0.d0
           oM3 = 1./smoc(k)
           M0 = (smob(k)*oM3)
           Mrat = smob(k)*M0*M0*M0
           slam1 = M0 * Lam0
           slam2 = M0 * Lam1
           do n = 1, nrbins
              x = am_s * xxDs(n)**bm_s
              call rayleigh_soak_wetgraupel (x, DBLE(ocms), DBLE(obms), &
     &              fmelt_s, melt_outside_s, m_w_0, m_i_0, lamda_radar, &
     &              CBACK, mixingrulestring_s, matrixstring_s,          &
     &              inclusionstring_s, hoststring_s,                    &
     &              hostmatrixstring_s, hostinclusionstring_s)
              f_d = Mrat*(Kap0*DEXP(-slam1*xxDs(n))                     &
     &              + Kap1*(M0*xxDs(n))**mu_s * DEXP(-slam2*xxDs(n)))
              eta = eta + f_d * CBACK * simpson(n) * xdts(n)
           enddo
           ze_snow(k) = SNGL(lamda4 / (pi5 * K_w) * eta)
          endif
          if (L_qg(k) .and. L_qg(k_0) ) then
           fmelt_g = MAX(0.05d0, MIN(1.0d0-rg(k)/rg(k_0), 0.99d0))
           eta = 0.d0
           lamg = 1./ilamg(k)
           do n = 1, nrbins
              x = am_g * xxDg(n)**bm_g
              call rayleigh_soak_wetgraupel (x, DBLE(ocmg), DBLE(obmg), &
     &              fmelt_g, melt_outside_g, m_w_0, m_i_0, lamda_radar, &
     &              CBACK, mixingrulestring_g, matrixstring_g,          &
     &              inclusionstring_g, hoststring_g,                    &
     &              hostmatrixstring_g, hostinclusionstring_g)
              f_d = N0_g(k)*xxDg(n)**mu_g * DEXP(-lamg*xxDg(n))
              eta = eta + f_d * CBACK * simpson(n) * xdtg(n)
           enddo
           ze_graupel(k) = SNGL(lamda4 / (pi5 * K_w) * eta)
          endif
       enddo
      endif
      do k = kte, kts, -1
         dBZ(k) = 10.*log10((ze_rain(k)+ze_snow(k)+ze_graupel(k))*1.d18)
      enddo
      end subroutine calc_refl10cm
      subroutine calc_refl10cm_card (qv1d, qc1d, qr1d, nr1d, qs1d, qg1d,     &
                          t1d, p1d, dBZ, kts, kte, ii, jj)
 use config, only: max_levels
 !$acc routine seq
      IMPLICIT NONE
      LOGICAL, PARAMETER:: iiwarm = .false.
      INTEGER, INTENT(IN):: kts, kte, ii, jj
      REAL, DIMENSION(kts:kte), INTENT(IN)::                            &
                          qv1d, qc1d, qr1d, nr1d, qs1d, qg1d, t1d, p1d
      REAL, DIMENSION(kts:kte), INTENT(INOUT):: dBZ
      REAL, DIMENSION(1:max_levels):: temp, pres, qv, rho, rhof
      REAL, DIMENSION(1:max_levels):: rc, rr, nr, rs, rg
      DOUBLE PRECISION, DIMENSION(1:max_levels):: ilamr, ilamg, N0_r, N0_g
      REAL, DIMENSION(1:max_levels):: mvd_r
      REAL, DIMENSION(1:max_levels):: smob, smo2, smoc, smoz
      REAL:: oM3, M0, Mrat, slam1, slam2, xDs
      REAL:: ils1, ils2, t1_vts, t2_vts, t3_vts, t4_vts
      REAL:: vtr_dbz_wt, vts_dbz_wt, vtg_dbz_wt
      REAL, DIMENSION(1:max_levels):: ze_rain, ze_snow, ze_graupel
      DOUBLE PRECISION:: N0_exp, N0_min, lam_exp, lamr, lamg
      REAL:: a_, b_, loga_, tc0
      DOUBLE PRECISION:: fmelt_s, fmelt_g
      INTEGER:: i, k, k_0, kbot, n
      LOGICAL:: melti
      LOGICAL, DIMENSION(1:max_levels):: L_qr, L_qs, L_qg
      DOUBLE PRECISION:: cback, x, eta, f_d
      REAL:: xslw1, ygra1, zans1
      do k = kts, kte
         dBZ(k) = -35.0
      enddo
      do k = kts, kte
         temp(k) = t1d(k)
         qv(k) = MAX(1.E-10, qv1d(k))
         pres(k) = p1d(k)
         rho(k) = 0.622*pres(k)/(R*temp(k)*(qv(k)+0.622))
         rhof(k) = SQRT(RHO_NOT/rho(k))
         rc(k) = MAX(R1, qc1d(k)*rho(k))
         if (qr1d(k) .gt. R1) then
            rr(k) = qr1d(k)*rho(k)
            nr(k) = MAX(R2, nr1d(k)*rho(k))
            lamr = (am_r*crg(3)*org2*nr(k)/rr(k))**obmr
            ilamr(k) = 1./lamr
            N0_r(k) = nr(k)*org2*lamr**cre(2)
            mvd_r(k) = (3.0 + mu_r + 0.672) * ilamr(k)
            L_qr(k) = .true.
         else
            rr(k) = R1
            nr(k) = R1
            mvd_r(k) = 50.E-6
            L_qr(k) = .false.
         endif
         if (qs1d(k) .gt. R2) then
            rs(k) = qs1d(k)*rho(k)
            L_qs(k) = .true.
         else
            rs(k) = R1
            L_qs(k) = .false.
         endif
         if (qg1d(k) .gt. R2) then
            rg(k) = qg1d(k)*rho(k)
            L_qg(k) = .true.
         else
            rg(k) = R1
            L_qg(k) = .false.
         endif
      enddo
      do k = kts, kte
         smo2(k) = 0.
         smob(k) = 0.
         smoc(k) = 0.
         smoz(k) = 0.
      enddo
      if (ANY(L_qs .eqv. .true.)) then
      do k = kts, kte
         if (.not. L_qs(k)) CYCLE
         tc0 = MIN(-0.1, temp(k)-273.15)
         smob(k) = rs(k)*oams
         if (bm_s.gt.(2.0-1.e-3) .and. bm_s.lt.(2.0+1.e-3)) then
            smo2(k) = smob(k)
         else
            loga_ = sa(1) + sa(2)*tc0 + sa(3)*bm_s &
     &         + sa(4)*tc0*bm_s + sa(5)*tc0*tc0 &
     &         + sa(6)*bm_s*bm_s + sa(7)*tc0*tc0*bm_s &
     &         + sa(8)*tc0*bm_s*bm_s + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*bm_s*bm_s*bm_s
            a_ = 10.0**loga_
            b_ = sb(1) + sb(2)*tc0 + sb(3)*bm_s &
     &         + sb(4)*tc0*bm_s + sb(5)*tc0*tc0 &
     &         + sb(6)*bm_s*bm_s + sb(7)*tc0*tc0*bm_s &
     &         + sb(8)*tc0*bm_s*bm_s + sb(9)*tc0*tc0*tc0 &
     &         + sb(10)*bm_s*bm_s*bm_s
            smo2(k) = (smob(k)/a_)**(1./b_)
         endif
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(1) &
     &         + sa(4)*tc0*cse(1) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(1)*cse(1) + sa(7)*tc0*tc0*cse(1) &
     &         + sa(8)*tc0*cse(1)*cse(1) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(1)*cse(1)*cse(1)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(1) + sb(4)*tc0*cse(1) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(1)*cse(1) &
     &        + sb(7)*tc0*tc0*cse(1) + sb(8)*tc0*cse(1)*cse(1) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(1)*cse(1)*cse(1)
         smoc(k) = a_ * smo2(k)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(3) &
     &         + sa(4)*tc0*cse(3) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(3)*cse(3) + sa(7)*tc0*tc0*cse(3) &
     &         + sa(8)*tc0*cse(3)*cse(3) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(3)*cse(3)*cse(3)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(3) + sb(4)*tc0*cse(3) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(3)*cse(3) &
     &        + sb(7)*tc0*tc0*cse(3) + sb(8)*tc0*cse(3)*cse(3) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(3)*cse(3)*cse(3)
         smoz(k) = a_ * smo2(k)**b_
      enddo
      endif
      if (ANY(L_qg .eqv. .true.)) then
      N0_min = gonv_max
      k_0 = kts
      do k = kte, kts, -1
         if (temp(k).ge.270.65) k_0 = MAX(k_0, k)
      enddo
      do k = kte, kts, -1
         if (k.gt.k_0 .and. L_qr(k) .and. mvd_r(k).gt.100.E-6) then
            xslw1 = 4.01 + alog10(mvd_r(k))
         else
            xslw1 = 0.01
         endif
         ygra1 = 4.31 + alog10(max(5.E-5, rg(k)))
         zans1 = 3.1 + (100./(300.*xslw1*ygra1/(10./xslw1+1.+0.25*ygra1)+30.+10.*ygra1))
         N0_exp = 10.**(zans1)
         N0_exp = MAX(DBLE(gonv_min), MIN(N0_exp, DBLE(gonv_max)))
         N0_min = MIN(N0_exp, N0_min)
         N0_exp = N0_min
         lam_exp = (N0_exp*am_g*cgg(1)/rg(k))**oge1
         lamg = lam_exp * (cgg(3)*ogg2*ogg1)**obmg
         ilamg(k) = 1./lamg
         N0_g(k) = N0_exp/(cgg(2)*lam_exp) * lamg**cge(2)
      enddo
      endif
      melti = .false.
      k_0 = kts
      do k = kte-1, kts, -1
         if ( (temp(k).gt.273.15) .and. L_qr(k)                         &
     &                            .and. (L_qs(k+1).or.L_qg(k+1)) ) then
            k_0 = MAX(k+1, k_0)
            melti=.true.
            goto 195
         endif
      enddo
 195  continue
      do k = kts, kte
         ze_rain(k) = 1.e-22
         ze_snow(k) = 1.e-22
         ze_graupel(k) = 1.e-22
         if (L_qr(k)) ze_rain(k) = N0_r(k)*crg(4)*ilamr(k)**cre(4)
         if (L_qs(k)) ze_snow(k) = (0.176/0.93) * (6.0/PI)*(6.0/PI)     &
     &                           * (am_s/900.0)*(am_s/900.0)*smoz(k)
         if (L_qg(k)) ze_graupel(k) = (0.176/0.93) * (6.0/PI)*(6.0/PI)  &
     &                              * (am_g/900.0)*(am_g/900.0)         &
     &                              * N0_g(k)*cgg(4)*ilamg(k)**cge(4)
      enddo
      if (.not. iiwarm .and. melti .and. k_0.ge.2) then
       do k = k_0-1, kts, -1
          if (L_qs(k) .and. L_qs(k_0) ) then
           fmelt_s = MAX(0.05d0, MIN(1.0d0-rs(k)/rs(k_0), 0.99d0))
           eta = 0.d0
           oM3 = 1./smoc(k)
           M0 = (smob(k)*oM3)
           Mrat = smob(k)*M0*M0*M0
           slam1 = M0 * Lam0
           slam2 = M0 * Lam1
           do n = 1, nrbins
              x = am_s * rc_xxDs(n)**bm_s
              call rayleigh_card (x, DBLE(ocms), DBLE(obms), fmelt_s, melt_outside_s, rc_m_w_0, rc_m_i_0, lamda_radar, CBACK)
              f_d = Mrat*(Kap0*DEXP(-slam1*rc_xxDs(n))                     &
     &              + Kap1*(M0*rc_xxDs(n))**mu_s * DEXP(-slam2*rc_xxDs(n)))
              eta = eta + f_d * CBACK * rc_simpson(n) * rc_xdts(n)
           enddo
           ze_snow(k) = SNGL(rc_lamda4 / (rc_PI5 * rc_K_w) * eta)
          endif
          if (L_qg(k) .and. L_qg(k_0) ) then
           fmelt_g = MAX(0.05d0, MIN(1.0d0-rg(k)/rg(k_0), 0.99d0))
           eta = 0.d0
           lamg = 1./ilamg(k)
           do n = 1, nrbins
              x = am_g * rc_xxDg(n)**bm_g
              call rayleigh_card (x, DBLE(ocmg), DBLE(obmg), fmelt_g, melt_outside_g, rc_m_w_0, rc_m_i_0, lamda_radar, CBACK)
              f_d = N0_g(k)*rc_xxDg(n)**mu_g * DEXP(-lamg*rc_xxDg(n))
              eta = eta + f_d * CBACK * rc_simpson(n) * rc_xdtg(n)
           enddo
           ze_graupel(k) = SNGL(rc_lamda4 / (rc_PI5 * rc_K_w) * eta)
          endif
       enddo
      endif
      do k = kte, kts, -1
         dBZ(k) = 10.*log10((ze_rain(k)+ze_snow(k)+ze_graupel(k))*1.d18)
      enddo
      end subroutine calc_refl10cm_card

      subroutine radar_card_start()
      integer :: n
      do n = 1, nrbins
       rc_xxDs(n) = xxDs(n); rc_xdts(n) = xdts(n); rc_xxDg(n) = xxDg(n); rc_xdtg(n) = xdtg(n)
      enddo
      do n = 1, nrbins+1
       rc_simpson(n) = simpson(n)
      enddo
      rc_K_w = K_w; rc_PI5 = PI5; rc_lamda4 = lamda4; rc_m_w_0 = m_w_0; rc_m_i_0 = m_i_0
      !$acc update device(rc_xxDs, rc_xdts, rc_xxDg, rc_xdtg, rc_simpson, rc_K_w, rc_PI5, rc_lamda4, rc_m_w_0, rc_m_i_0)
      end subroutine radar_card_start

      ! module_mp_radar's m_complex_maxwellgarnett with inclusion 'spheroidal', its result in res (as a complex function the
      ! card gave NaN for the second call of rayleigh_card, nvfortran 25.3)
      SUBROUTINE mg_spheroidal_card(vol1, vol2, vol3, m1, m2, m3, error, res)
      !$acc routine seq
      IMPLICIT NONE
      COMPLEX(KIND=R8KIND), INTENT(IN) :: m1, m2, m3
      DOUBLE PRECISION, INTENT(IN) :: vol1, vol2, vol3
      INTEGER, INTENT(out) :: error
      COMPLEX(KIND=R8KIND), INTENT(out) :: res
      COMPLEX(KIND=R8KIND) :: beta2, beta3, m1t, m2t, m3t
      error = 0
      if (DABS(vol1+vol2+vol3-1.0d0) .gt. 1d-6) then
       res=CMPLX(-999.99d0,-999.99d0)
       error = 1
       return
      endif
      m1t = m1**2
      m2t = m2**2
      m3t = m3**2
      beta2 = 2.0d0*m1t/(m2t-m1t) * (m2t/(m2t-m1t)*LOG(m2t/m1t)-1.0d0)
      beta3 = 2.0d0*m1t/(m3t-m1t) * (m3t/(m3t-m1t)*LOG(m3t/m1t)-1.0d0)
      res = &
       SQRT(((1.0d0-vol2-vol3)*m1t + vol2*beta2*m2t + vol3*beta3*m3t) / &
       (1.0d0-vol2-vol3+vol2*beta2+vol3*beta3))
      END SUBROUTINE mg_spheroidal_card

      ! module_mp_radar's rayleigh_soak_wetgraupel for radar_init's strings: get_m_mix_nested with host 'air', matrix 'water',
      ! hostmatrix 'icewater' (get_m_mix with matrix 'water', then with matrix 'ice'), mixing rule maxwellgarnett, spheroidal
      subroutine rayleigh_card (x_g, a_geo, b_geo, fmelt, meltratio_outside, m_w, m_i, lambda, C_back)
      !$acc routine seq
      IMPLICIT NONE
      DOUBLE PRECISION, INTENT(in):: x_g, a_geo, b_geo, fmelt, lambda, meltratio_outside
      DOUBLE PRECISION, INTENT(out):: C_back
      COMPLEX(KIND=R8KIND), INTENT(in):: m_w, m_i
      COMPLEX(KIND=R8KIND):: m_core, m_air, mtmp, m_two
      DOUBLE PRECISION:: D_large, D_g, rhog, x_w, xw_a, fm, fmgrenz, volg, vg, volair, volice, volwater, &
                         meltratio_outside_grenz, mra, vol1, vol2
      INTEGER:: error, cumulerror
      DOUBLE PRECISION, PARAMETER:: PIx=3.1415926535897932384626434d0
      m_air = (1.0d0,0.0d0)
      fm = DMAX1(DMIN1(fmelt, 1.0d0), 0.0d0)
      mra = DMAX1(DMIN1(meltratio_outside, 1.0d0), 0.0d0)
      mra = mra + (1.0d0-mra)*fm
      x_w = x_g * fm
      D_g = a_geo * x_g**b_geo
      if (D_g .ge. 1d-12) then
       vg = PIx/6. * D_g**3
       rhog = DMAX1(DMIN1(x_g / vg, 900.0d0), 10.0d0)
       vg = x_g / rhog
       meltratio_outside_grenz = 1.0d0 - rhog / 1000.
       if (mra .le. meltratio_outside_grenz) then
        volg = vg * (1.0d0 - mra * fm)
       else
        fmgrenz=(900.0-rhog)/(mra*900.0-rhog+900.0*rhog/1000.)
        if (fm .le. fmgrenz) then
         volg = (1.0 - mra * fm) * vg
        else
         volg = (x_g - x_w) / 900.0 + x_w / 1000.
        endif
       endif
       D_large  = (6.0 / PIx * volg) ** (1./3.)
       volice = (x_g - x_w) / (volg * 900.0)
       volwater = x_w / (1000. * volg)
       volair = 1.0 - volice - volwater
       ! get_m_mix_nested (m_air, m_i, m_w, volair, volice, volwater, ...)
       cumulerror = 0
       m_core = CMPLX(1.0d0,0.0d0)
       vol1 = volice / MAX(volice+volwater,1d-10)
       vol2 = 1.0d0 - vol1
       ! get_m_mix (m_a=m_air, m_i, m_w, 0, vol1, vol2), matrix water: maxwellgarnett(volwater, volair, volice, m_w, m_a, m_i)
       call mg_spheroidal_card(vol2, 0.0d0, vol1, m_w, m_air, m_i, error, mtmp)
       cumulerror = cumulerror + error
       ! get_m_mix (m_a=m_air, m_i=mtmp, m_w=2*m_a, volair, 1-volair, 0), matrix ice: maxwellgarnett(volice, volair, volwater,
       ! m_i, m_a, m_w)
       m_two = 2.0*m_air
       call mg_spheroidal_card((1.0d0-volair), volair, 0.0d0, mtmp, m_air, m_two, error, m_core)
       cumulerror = cumulerror + error
       if (cumulerror .ne. 0) m_core = CMPLX(1.0d0,0.0d0)
       if (cumulerror .ne. 0) then
        C_back = 0.0d0
        return
       endif
       C_back = (ABS((m_core**2-1.0d0)/(m_core**2+2.0d0)))**2 * rc_PI5 * D_large**6 / rc_lamda4
      else
       C_back = 0.0d0
      endif
      end subroutine rayleigh_card

      REAL(KIND=RKIND) FUNCTION RSLF_dev(P,T)
 !$acc routine seq

      IMPLICIT NONE
      REAL(KIND=RKIND), INTENT(IN):: P, T
      REAL(KIND=RKIND):: ESL,X
      REAL(KIND=RKIND), PARAMETER:: C0= .611583699E03
      REAL(KIND=RKIND), PARAMETER:: C1= .444606896E02
      REAL(KIND=RKIND), PARAMETER:: C2= .143177157E01
      REAL(KIND=RKIND), PARAMETER:: C3= .264224321E-1
      REAL(KIND=RKIND), PARAMETER:: C4= .299291081E-3
      REAL(KIND=RKIND), PARAMETER:: C5= .203154182E-5
      REAL(KIND=RKIND), PARAMETER:: C6= .702620698E-8
      REAL(KIND=RKIND), PARAMETER:: C7= .379534310E-11
      REAL(KIND=RKIND), PARAMETER:: C8=-.321582393E-13

      X=MAX(-80.,T-273.16)

!     ESL=612.2*EXP(17.67*X/(T-29.65))
      ESL=C0+X*(C1+X*(C2+X*(C3+X*(C4+X*(C5+X*(C6+X*(C7+X*C8)))))))
      ESL=MIN(ESL, P*0.15)  ! Even with P=1050mb and T=55C, the sat. vap. pres only contributes to
      RSLF_dev=.622*ESL/(P-ESL) ! ~15% of total pres.

!    ALTERNATIVE
!  ; Source: Murphy and Koop, Review of the vapour pressure of ice and
!             supercooled water for atmospheric applications, Q. J. R.
!             Meteorol. Soc (2005), 131, pp. 1539-1565.
!    ESL = EXP(54.842763 - 6763.22 / T - 4.210 * ALOG(T) + 0.000367 * T
!        + TANH(0.0415 * (T - 218.8)) * (53.878 - 1331.22
!        / T - 9.44523 * ALOG(T) + 0.014025 * T))

      END FUNCTION RSLF_dev

      REAL(KIND=RKIND) FUNCTION RSIF_dev(P,T)
 !$acc routine seq

      IMPLICIT NONE
      REAL(KIND=RKIND), INTENT(IN):: P, T
      REAL(KIND=RKIND):: ESI,X
      REAL(KIND=RKIND), PARAMETER:: C0= .609868993E03
      REAL(KIND=RKIND), PARAMETER:: C1= .499320233E02
      REAL(KIND=RKIND), PARAMETER:: C2= .184672631E01
      REAL(KIND=RKIND), PARAMETER:: C3= .402737184E-1
      REAL(KIND=RKIND), PARAMETER:: C4= .565392987E-3
      REAL(KIND=RKIND), PARAMETER:: C5= .521693933E-5
      REAL(KIND=RKIND), PARAMETER:: C6= .307839583E-7
      REAL(KIND=RKIND), PARAMETER:: C7= .105785160E-9
      REAL(KIND=RKIND), PARAMETER:: C8= .161444444E-12

      X=MAX(-80.,T-273.16)
      ESI=C0+X*(C1+X*(C2+X*(C3+X*(C4+X*(C5+X*(C6+X*(C7+X*C8)))))))
      ESI=MIN(ESI, P*0.15)
      RSIF_dev=.622*ESI/(P-ESI)

!    ALTERNATIVE
!  ; Source: Murphy and Koop, Review of the vapour pressure of ice and
!             supercooled water for atmospheric applications, Q. J. R.
!             Meteorol. Soc (2005), 131, pp. 1539-1565.
!     ESI = EXP(9.550426 - 5723.265/T + 3.53068*ALOG(T) - 0.00728332*T)

      END FUNCTION RSIF_dev

! ---- hand-written: tools/thompson_card.f90 (not generated from the original) ----
      ! the arrays of the hand-written stages for slots columns, and the constants of the dry points (rain_size_moments for
      ! rr = R1, nr = R2; the graupel N0 of snow_graupel_moments for xslw1 = 0.01, rg = R1; b1's idx_n for nc = 2), computed on
      ! the card
      subroutine thompson_card_start(slots)
      integer, intent(in) :: slots
      DOUBLE PRECISION:: lamr, N0_exp
      REAL:: rr1, nr1, rg1, xslw1, ygra1, zans1, mvd, nc1
      INTEGER:: idx_n
      if (allocated(th_n0)) return
      allocate(th_n0(slots, kte+1), th_xs(slots, kte), th_odz(slots, kte), th_orho(slots, kte), th_vt(slots, kte+1, 6), th_on(slots, 4), th_k0(slots), th_k0b(slots), th_ks(slots, 4), th_any(slots, 4))
      !$acc serial
      rr1 = R1
      nr1 = R2
      lamr = (am_r*crg(3)*org2*nr1/rr1)**obmr
      th_dry_ilamr = 1./lamr
      mvd = (3.0 + mu_r + 0.672) / lamr
      th_dry_mvdr = mvd
      th_dry_n0r = nr1*org2*lamr**cre(2)
      rg1 = R1
      xslw1 = 0.01
      ygra1 = 4.31 + alog10(max(5.E-5, rg1))
      zans1 = 3.1 + (100./(300.*xslw1*ygra1/(10./xslw1+1.+0.25*ygra1)+30.+10.*ygra1))
      N0_exp = 10.**(zans1)
      N0_exp = MAX(DBLE(gonv_min), MIN(N0_exp, DBLE(gonv_max)))
      th_dry_n0g = N0_exp
      nc1 = 2.
      idx_n = NINT(1.0 + FLOAT(nbc) * DLOG(nc1/t_Nc(1)) / nic1)
      th_dry_idxn = idx_n
      !$acc end serial
      end subroutine thompson_card_start

      ! the graupel N0 of one level before the running minimum (snow_graupel_moments, update_size_distributions)
      subroutine th_n0_level(slot_, k, kb)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      logical, intent(in) :: kb   ! k_0 of c1 (th_k0b), else of a2 (th_k0)
      REAL:: xslw1, ygra1, zans1
      DOUBLE PRECISION:: N0_exp
      integer :: k_0
      k_0 = th_k0(slot_)
      if (kb) k_0 = th_k0b(slot_)
      if (.not. kb) then   ! a2: the rain's term from a1's mvd_r, kept by th_moments (th_xs, -1 without)
         if (k.gt.k_0 .and. th_xs(slot_,k) .gt. 0.) then
            xslw1 = th_xs(slot_,k)
         else
            if (pool_pr(slot_,k,tp_rg) .le. 5.E-5) then
               th_n0(slot_,k) = th_dry_n0g
               return
            endif
            xslw1 = 0.01
         endif
      elseif (k.gt.k_0 .and. pool_pl(slot_,k,tl_l_qr) .and. pool_pr(slot_,k,tp_mvd_r).gt.100.E-6) then
         xslw1 = 4.01 + alog10(pool_pr(slot_,k,tp_mvd_r))
      else
         if (pool_pr(slot_,k,tp_rg) .le. 5.E-5) then   ! max(5.E-5, rg) = 5.E-5, xslw1 = 0.01: the dry constant
            th_n0(slot_,k) = th_dry_n0g
            return
         endif
         xslw1 = 0.01
      endif
      ygra1 = 4.31 + alog10(max(5.E-5, pool_pr(slot_,k,tp_rg)))
      zans1 = 3.1 + (100./(300.*xslw1*ygra1/(10./xslw1+1.+0.25*ygra1)+30.+10.*ygra1))
      N0_exp = 10.**(zans1)
      N0_exp = MAX(DBLE(gonv_min), MIN(N0_exp, DBLE(gonv_max)))
      th_n0(slot_,k) = N0_exp
      end subroutine th_n0_level

      ! the running minimum of the graupel N0 from the top (N0_min = MIN(N0_exp, N0_min); N0_exp = N0_min)
      subroutine th_n0_scan(slot_)
      !$acc routine seq
      integer, intent(in) :: slot_
      integer :: k
      DOUBLE PRECISION:: N0_min
      N0_min = gonv_max
      do k = kte, 1, -1
         N0_min = MIN(th_n0(slot_,k), N0_min)
         th_n0(slot_,k) = N0_min
      enddo
      end subroutine th_n0_scan

      ! lam_exp, ilamg, N0_g of one level from the running minimum, where they are read (rg > R1 or L_qg)
      subroutine th_graupel_level(slot_, k)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      DOUBLE PRECISION:: N0_exp, lam_exp, lamg
      if (.not. (pool_pr(slot_,k,tp_rg) .gt. R1 .or. pool_pl(slot_,k,tl_l_qg))) return
      N0_exp = th_n0(slot_,k)
      lam_exp = (N0_exp*am_g*cgg(1)/pool_pr(slot_,k,tp_rg))**oge1
      lamg = lam_exp * (cgg(3)*ogg2*ogg1)**obmg
      pool_pd(slot_,k,td_ilamg) = 1./lamg
      pool_pd(slot_,k,td_n0_g) = N0_exp/(cgg(2)*lam_exp) * lamg**cge(2)
      end subroutine th_graupel_level

      ! mp_thompson_a2 at one level: the snow moments (L_qs), the graupel N0 before the minimum (it reads mvd_r before the rain
      ! moments renew it, as in a2), the rain moments (the dry constants where rr = R1 and nr = R2)
      subroutine th_moments(slot_, k)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      REAL:: a_, b_, loga_, tc0
      DOUBLE PRECISION:: lamr
      if (pool_pl(slot_,k,tl_l_qs)) then
         tc0 = MIN(-0.1, pool_pr(slot_,k,tp_temp)-273.15)
         pool_pr(slot_,k,tp_smob) = pool_pr(slot_,k,tp_rs)*oams
         if (bm_s.gt.(2.0-1.e-3) .and. bm_s.lt.(2.0+1.e-3)) then
            pool_pr(slot_,k,tp_smo2) = pool_pr(slot_,k,tp_smob)
         else
            loga_ = sa(1) + sa(2)*tc0 + sa(3)*bm_s &
               + sa(4)*tc0*bm_s + sa(5)*tc0*tc0 &
               + sa(6)*bm_s*bm_s + sa(7)*tc0*tc0*bm_s &
               + sa(8)*tc0*bm_s*bm_s + sa(9)*tc0*tc0*tc0 &
               + sa(10)*bm_s*bm_s*bm_s
            a_ = 10.0**loga_
            b_ = sb(1) + sb(2)*tc0 + sb(3)*bm_s &
               + sb(4)*tc0*bm_s + sb(5)*tc0*tc0 &
               + sb(6)*bm_s*bm_s + sb(7)*tc0*tc0*bm_s &
               + sb(8)*tc0*bm_s*bm_s + sb(9)*tc0*tc0*tc0 &
               + sb(10)*bm_s*bm_s*bm_s
            pool_pr(slot_,k,tp_smo2) = (pool_pr(slot_,k,tp_smob)/a_)**(1./b_)
         endif
         loga_ = sa(1) + sa(2)*tc0 + sa(5)*tc0*tc0 + sa(9)*tc0*tc0*tc0
         a_ = 10.0**loga_
         b_ = sb(1) + sb(2)*tc0 + sb(5)*tc0*tc0 + sb(9)*tc0*tc0*tc0
         pool_pr(slot_,k,tp_smo0) = a_ * pool_pr(slot_,k,tp_smo2)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3) &
               + sa(4)*tc0 + sa(5)*tc0*tc0 &
               + sa(6) + sa(7)*tc0*tc0 &
               + sa(8)*tc0 + sa(9)*tc0*tc0*tc0 &
               + sa(10)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3) + sb(4)*tc0 &
              + sb(5)*tc0*tc0 + sb(6) &
              + sb(7)*tc0*tc0 + sb(8)*tc0 &
              + sb(9)*tc0*tc0*tc0 + sb(10)
         pool_pr(slot_,k,tp_smo1) = a_ * pool_pr(slot_,k,tp_smo2)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(1) &
               + sa(4)*tc0*cse(1) + sa(5)*tc0*tc0 &
               + sa(6)*cse(1)*cse(1) + sa(7)*tc0*tc0*cse(1) &
               + sa(8)*tc0*cse(1)*cse(1) + sa(9)*tc0*tc0*tc0 &
               + sa(10)*cse(1)*cse(1)*cse(1)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(1) + sb(4)*tc0*cse(1) &
              + sb(5)*tc0*tc0 + sb(6)*cse(1)*cse(1) &
              + sb(7)*tc0*tc0*cse(1) + sb(8)*tc0*cse(1)*cse(1) &
              + sb(9)*tc0*tc0*tc0 + sb(10)*cse(1)*cse(1)*cse(1)
         pool_pr(slot_,k,tp_smoc) = a_ * pool_pr(slot_,k,tp_smo2)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(13) &
               + sa(4)*tc0*cse(13) + sa(5)*tc0*tc0 &
               + sa(6)*cse(13)*cse(13) + sa(7)*tc0*tc0*cse(13) &
               + sa(8)*tc0*cse(13)*cse(13) + sa(9)*tc0*tc0*tc0 &
               + sa(10)*cse(13)*cse(13)*cse(13)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(13) + sb(4)*tc0*cse(13) &
              + sb(5)*tc0*tc0 + sb(6)*cse(13)*cse(13) &
              + sb(7)*tc0*tc0*cse(13) + sb(8)*tc0*cse(13)*cse(13) &
              + sb(9)*tc0*tc0*tc0 + sb(10)*cse(13)*cse(13)*cse(13)
         pool_pr(slot_,k,tp_smoe) = a_ * pool_pr(slot_,k,tp_smo2)**b_
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(16) &
               + sa(4)*tc0*cse(16) + sa(5)*tc0*tc0 &
               + sa(6)*cse(16)*cse(16) + sa(7)*tc0*tc0*cse(16) &
               + sa(8)*tc0*cse(16)*cse(16) + sa(9)*tc0*tc0*tc0 &
               + sa(10)*cse(16)*cse(16)*cse(16)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(16) + sb(4)*tc0*cse(16) &
              + sb(5)*tc0*tc0 + sb(6)*cse(16)*cse(16) &
              + sb(7)*tc0*tc0*cse(16) + sb(8)*tc0*cse(16)*cse(16) &
              + sb(9)*tc0*tc0*tc0 + sb(10)*cse(16)*cse(16)*cse(16)
         pool_pr(slot_,k,tp_smof) = a_ * pool_pr(slot_,k,tp_smo2)**b_
      endif
      ! the rain's term of the graupel N0 (snow_graupel_moments) from a1's mvd_r, before the rain moments renew it; the k_0 test
      ! comes later (th_n0_level), when the column's k_0 is known
      if (pool_pl(slot_,k,tl_l_qr) .and. pool_pr(slot_,k,tp_mvd_r).gt.100.E-6) then
         th_xs(slot_,k) = 4.01 + alog10(pool_pr(slot_,k,tp_mvd_r))
      else
         th_xs(slot_,k) = -1.
      endif
      if (pool_pr(slot_,k,tp_rr) .eq. R1 .and. pool_pr(slot_,k,tp_nr) .eq. R2) then
         pool_pd(slot_,k,td_ilamr) = th_dry_ilamr
         pool_pr(slot_,k,tp_mvd_r) = th_dry_mvdr
         pool_pd(slot_,k,td_n0_r) = th_dry_n0r
      else
         lamr = (am_r*crg(3)*org2*pool_pr(slot_,k,tp_nr)/pool_pr(slot_,k,tp_rr))**obmr
         pool_pd(slot_,k,td_ilamr) = 1./lamr
         pool_pr(slot_,k,tp_mvd_r) = (3.0 + mu_r + 0.672) / lamr
         pool_pd(slot_,k,td_n0_r) = pool_pr(slot_,k,tp_nr)*org2*lamr**cre(2)
      endif
      end subroutine th_moments

      ! k_0 of a2 (th_k0) and of c1 (th_k0b) and the columns' species (th_any) as marks of the points: reset per column, then
      ! each point raises k_0 (an atomic MAX) and sets the flags of the species it has (th_marks_a after a1, th_marks_b after b1u)
      subroutine th_reset(slot_)
      !$acc routine seq
      integer, intent(in) :: slot_
      th_k0(slot_) = 1
      th_k0b(slot_) = 1
      th_any(slot_,1) = .false.
      th_any(slot_,2) = .false.
      th_any(slot_,3) = .false.
      th_any(slot_,4) = .false.
      end subroutine th_reset

      ! after a1: the temperature of the level is t1d (a1's temp)
      subroutine th_marks_a(slot_, k)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      if (pool_mc(slot_,k,tm_t1d).ge.270.65) then
         !$acc atomic update
         th_k0(slot_) = MAX(th_k0(slot_), k)
      endif
      end subroutine th_marks_a

      ! after b1u (the updated temperature and species; b2 changes only L_qc)
      subroutine th_marks_b(slot_, k)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      if (pool_pr(slot_,k,tp_temp).ge.270.65) then
         !$acc atomic update
         th_k0b(slot_) = MAX(th_k0b(slot_), k)
      endif
      if (pool_pl(slot_,k,tl_l_qr)) th_any(slot_,1) = .true.
      if (pool_pl(slot_,k,tl_l_qi)) th_any(slot_,2) = .true.
      if (pool_pl(slot_,k,tl_l_qs)) th_any(slot_,3) = .true.
      if (pool_pl(slot_,k,tl_l_qg)) th_any(slot_,4) = .true.
      end subroutine th_marks_b

      ! mp_thompson_c2's fall speeds at one level (after b2): rhof renewed where the column has rain (the rain loop renews it at
      ! every level), then rain, ice, snow and graupel where the species is at this level. Snow above T_0+0.1 and graupel above
      ! T_0 keep their own fall speed here; th_fall_species mixes in the rain's (vtrk of this level, taken from above where needed).
      subroutine th_fall_level(slot_, k)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, k
      DOUBLE PRECISION:: lamr, lami, ilami
      REAL:: vtr, vti, vts, vtg, xDs, Mrat, ils1, ils2, t1_vts, t2_vts, t3_vts, t4_vts
      if (th_any(slot_,1)) then
         pool_pr(slot_,k,tp_rhof) = SQRT(RHO_NOT/pool_pr(slot_,k,tp_rho))
         if (pool_pr(slot_,k,tp_rr).gt. R1) then
          lamr = (am_r*crg(3)*org2*pool_pr(slot_,k,tp_nr)/pool_pr(slot_,k,tp_rr))**obmr
          vtr = pool_pr(slot_,k,tp_rhof)*av_r*crg(6)*org3 * lamr**cre(3)                 &
                      *((lamr+fv_r)**(-cre(6)))
          th_vt(slot_,k,1) = vtr
          vtr = pool_pr(slot_,k,tp_rhof)*av_r*crg(7)/crg(12) * lamr**cre(12)             &
                      *((lamr+fv_r)**(-cre(7)))
          th_vt(slot_,k,2) = vtr
         endif
      endif
      if (th_any(slot_,2)) then
          if (pool_pr(slot_,k,tp_ri).gt. R1) then
           lami = (am_i*cig(2)*oig1*pool_pr(slot_,k,tp_ni)/pool_pr(slot_,k,tp_ri))**obmi
           ilami = 1./lami
           vti = pool_pr(slot_,k,tp_rhof)*av_i*cig(3)*oig2 * ilami**bv_i
           th_vt(slot_,k,3) = vti
           vti = pool_pr(slot_,k,tp_rhof)*av_i*cig(6)/cig(7) * ilami**bv_i
           th_vt(slot_,k,4) = vti
          endif
      endif
      if (th_any(slot_,3)) then
          if (pool_pr(slot_,k,tp_rs).gt. R1) then
           xDs = pool_pr(slot_,k,tp_smoc) / pool_pr(slot_,k,tp_smob)
           Mrat = 1./xDs
           ils1 = 1./(Mrat*Lam0 + fv_s)
           ils2 = 1./(Mrat*Lam1 + fv_s)
           t1_vts = Kap0*csg(4)*ils1**cse(4)
           t2_vts = Kap1*Mrat**mu_s*csg(10)*ils2**cse(10)
           ils1 = 1./(Mrat*Lam0)
           ils2 = 1./(Mrat*Lam1)
           t3_vts = Kap0*csg(1)*ils1**cse(1)
           t4_vts = Kap1*Mrat**mu_s*csg(7)*ils2**cse(7)
           vts = pool_pr(slot_,k,tp_rhof)*av_s * (t1_vts+t2_vts)/(t3_vts+t4_vts)
           if (pool_pr(slot_,k,tp_temp).gt. (T_0+0.1)) then
            th_vt(slot_,k,5) = vts
           else
            th_vt(slot_,k,5) = vts*pool_pr(slot_,k,tp_vts_boost)
           endif
          endif
      endif
      if (th_any(slot_,4)) then
          if (pool_pr(slot_,k,tp_rg).gt. R1) then
           vtg = pool_pr(slot_,k,tp_rhof)*av_g*cgg(6)*ogg3 * pool_pd(slot_,k,td_ilamg)**bv_g
           th_vt(slot_,k,6) = vtg
          endif
      endif
      ! 1/dzq and 1/rho of the level for the sedimentation (c2 forms them again at every level of every sub-step: the same
      ! expressions on values the sedimentation does not change)
      th_odz(slot_,k) = 1./pool_mc(slot_,k,tm_dzq)
      th_orho(slot_,k) = 1./pool_pr(slot_,k,tp_rho)
      end subroutine th_fall_level

      ! mp_thompson_c2's fall-speed loop of one species n (1 rain, 2 ice, 3 snow, 4 graupel) without its transcendental part
      ! (th_fall_level): a level without the species takes the fall speed of the level above, snow and graupel mix in the rain's,
      ! ksed1 and nstep. One thread per (column, species) (micro_staged); snow and graupel take the rain's fall speed from above in
      ! a register from th_vt's rain values at the levels with rain, which the rain's thread leaves as they are (it writes only the
      ! levels without rain), so the threads of one column need no order.
      subroutine th_fall_species(slot_, n, dt)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, n
      REAL, intent(in) :: dt
      integer :: k, nstep, ks, iv
      REAL:: delta_tp, SR, vts, vr, vrn
      th_on(slot_,n) = 1.0
      th_ks(slot_,n) = 1
      if (.not. th_any(slot_,n)) return
      nstep = 0
      ks = 1
      vr = 0.
      vrn = 0.
      iv = 1
      if (n .eq. 2) iv = 3
      if (n .eq. 3) iv = 5
      if (n .eq. 4) iv = 6
      th_vt(slot_,kte+1,iv) = 0.
      if (n .le. 2) th_vt(slot_,kte+1,iv+1) = 0.
      do k = kte, 1, -1
         if (n .eq. 1) then
            if (.not. (pool_pr(slot_,k,tp_rr).gt. R1)) then
             th_vt(slot_,k,1) = th_vt(slot_,k+1,1)
             th_vt(slot_,k,2) = th_vt(slot_,k+1,2)
            endif
            if (MAX(th_vt(slot_,k,1),th_vt(slot_,k,2)) .gt. 1.E-3) then
               ks = MAX(ks, k)
               delta_tp = pool_mc(slot_,k,tm_dzq)/(MAX(th_vt(slot_,k,1),th_vt(slot_,k,2)))
               if (DT/delta_tp + 1. .lt. 2147483648.) nstep = MAX(nstep, INT(DT/delta_tp + 1.))
            endif
         elseif (n .eq. 2) then
            if (.not. (pool_pr(slot_,k,tp_ri).gt. R1)) then
             th_vt(slot_,k,3) = th_vt(slot_,k+1,3)
             th_vt(slot_,k,4) = th_vt(slot_,k+1,4)
            endif
            if (th_vt(slot_,k,3) .gt. 1.E-3) then
               ks = MAX(ks, k)
               delta_tp = pool_mc(slot_,k,tm_dzq)/th_vt(slot_,k,3)
               if (DT/delta_tp + 1. .lt. 2147483648.) nstep = MAX(nstep, INT(DT/delta_tp + 1.))
            endif
         else
            ! the rain's fall speed of this level (vtrk of c2: zero without rain in the column, else from above)
            if (th_any(slot_,1)) then
               if (pool_pr(slot_,k,tp_rr).gt. R1) vr = th_vt(slot_,k,1)
            endif
            if (n .eq. 3) then
               if (pool_pr(slot_,k,tp_rs).gt. R1) then
                if (pool_pr(slot_,k,tp_temp).gt. (T_0+0.1)) then
                 vts = th_vt(slot_,k,5)
                 SR = pool_pr(slot_,k,tp_rs)/(pool_pr(slot_,k,tp_rs)+pool_pr(slot_,k,tp_rr))
                 th_vt(slot_,k,5) = vts*SR + (1.-SR)*vr
                endif
               else
                th_vt(slot_,k,5) = th_vt(slot_,k+1,5)
               endif
               if (th_vt(slot_,k,5) .gt. 1.E-3) then
                  ks = MAX(ks, k)
                  delta_tp = pool_mc(slot_,k,tm_dzq)/th_vt(slot_,k,5)
                  if (DT/delta_tp + 1. .lt. 2147483648.) nstep = MAX(nstep, INT(DT/delta_tp + 1.))
               endif
            else
               if (pool_pr(slot_,k,tp_rg).gt. R1) then
                if (pool_pr(slot_,k,tp_temp).gt. T_0) then
                 th_vt(slot_,k,6) = MAX(th_vt(slot_,k,6), vr)
                endif
               else
                th_vt(slot_,k,6) = th_vt(slot_,k+1,6)
               endif
               if (th_vt(slot_,k,6) .gt. 1.E-3) then
                  ks = MAX(ks, k)
                  delta_tp = pool_mc(slot_,k,tm_dzq)/th_vt(slot_,k,6)
                  if (DT/delta_tp + 1. .lt. 2147483648.) nstep = MAX(nstep, INT(DT/delta_tp + 1.))
               endif
            endif
         endif
      enddo
      if (ks .eq. kte) ks = kte-1
      th_ks(slot_,n) = ks
      if (nstep .gt. 0) th_on(slot_,n) = 1./REAL(nstep)
      end subroutine th_fall_species

      ! mp_thompson_c2's sedimentation of one species s (1 rain, 2 cloud water, 3 ice, 4 snow, 5 graupel) of one column; ppt the
      ! column's (pptrain, pptsnow, pptgraul, pptice). Each sub-step top-down: sa the flux of the level above at the start of the
      ! sub-step, sk this level's (the original's sed_*(k+1), sed_*(k)).
      subroutine th_sediment(slot_, s, dt, ppt)
      use micro_pool
      !$acc routine seq
      integer, intent(in) :: slot_, s
      REAL, intent(in) :: dt
      REAL, intent(inout) :: ppt(4)
      integer :: k, n, it, nstep, ks, iv, ir, ivn, inn, iten, inten, ip
      REAL:: onstep, odzq, orho, sa, sk, san, skn, hgt_agl, vtc, pp
      DOUBLE PRECISION:: lamc, ilamc
      INTEGER:: nu_c
      LOGICAL:: any_qc
      if (s .eq. 2) then   ! cloud water: fall speeds of the lowest 500 m and one pass (no sub-steps)
       any_qc = .false.
       do k = 1, kte
          if (pool_pl(slot_,k,tl_l_qc)) any_qc = .true.
       enddo
       if (.not. any_qc) return
       ks = 1
       hgt_agl = 0.
       do k = 1, kte-1
          if (pool_pr(slot_,k,tp_rc) .gt. R2) ks = k
          hgt_agl = hgt_agl + pool_mc(slot_,k,tm_dzq)
          if (hgt_agl .gt. 500.0) exit
       enddo
       ! the level above ks has vtck = vtnck = 0 (sed_c = 0*rc, sed_n = 0*nc)
       sa = 0.*pool_pr(slot_,ks+1,tp_rc)
       san = 0.*pool_pr(slot_,ks+1,tp_nc)
       do k = ks, 1, -1
          sk = 0.
          skn = 0.
          if (pool_pr(slot_,k,tp_rc) .gt. R1 .and. pool_mc(slot_,k,tm_w1d) .lt. 1.E-1) then
           nu_c = MIN(15, NINT(1000.E6/pool_pr(slot_,k,tp_nc)) + 2)
           lamc = (pool_pr(slot_,k,tp_nc)*am_r*ccg(2,nu_c)*ocg1(nu_c)/pool_pr(slot_,k,tp_rc))**obmr
           ilamc = 1./lamc
           vtc = pool_pr(slot_,k,tp_rhof)*av_c*ccg(5,nu_c)*ocg2(nu_c) * ilamc**bv_c
           sk = vtc*pool_pr(slot_,k,tp_rc)
           vtc = pool_pr(slot_,k,tp_rhof)*av_c*ccg(4,nu_c)*ocg1(nu_c) * ilamc**bv_c
           skn = vtc*pool_pr(slot_,k,tp_nc)
          else
           sk = 0.*pool_pr(slot_,k,tp_rc)
           skn = 0.*pool_pr(slot_,k,tp_nc)
          endif
          odzq = th_odz(slot_,k)
          orho = th_orho(slot_,k)
          pool_pr(slot_,k,tp_qcten) = pool_pr(slot_,k,tp_qcten) + (sa-sk) *odzq*orho
          pool_pr(slot_,k,tp_ncten) = pool_pr(slot_,k,tp_ncten) + (san-skn) *odzq*orho
          pool_pr(slot_,k,tp_rc) = MAX(R1, pool_pr(slot_,k,tp_rc) + (sa-sk) *odzq*DT)
          pool_pr(slot_,k,tp_nc) = MAX(10., pool_pr(slot_,k,tp_nc) + (san-skn) *odzq*DT)
          sa = sk
          san = skn
       enddo
       return
      endif
      ! rain (1), ice (3), snow (4), graupel (5): n their index in th_any, th_on, th_ks; iv, ivn their fall speeds in th_vt (number
      ! 0: none); ir, inn the mass and number fields, iten, inten their tendencies; ip their sum in ppt
      select case (s)
      case (1)
       n = 1; iv = 1; ivn = 2; ir = tp_rr; inn = tp_nr; iten = tp_qrten; inten = tp_nrten; ip = 1
      case (3)
       n = 2; iv = 3; ivn = 4; ir = tp_ri; inn = tp_ni; iten = tp_qiten; inten = tp_niten; ip = 4
      case (4)
       n = 3; iv = 5; ivn = 0; ir = tp_rs; inn = 0; iten = tp_qsten; inten = 0; ip = 2
      case default
       n = 4; iv = 6; ivn = 0; ir = tp_rg; inn = 0; iten = tp_qgten; inten = 0; ip = 3
      end select
      if (.not. th_any(slot_,n)) return
      onstep = th_on(slot_,n)
      ks = th_ks(slot_,n)
      pp = ppt(ip)
      nstep = NINT(1./onstep)
      do it = 1, nstep
         ! the top level: its own flux out (sed(kte) at the start of the sub-step); the flux into ks from above
         k = kte
         sk = th_vt(slot_,k,iv)*pool_pr(slot_,k,ir)
         if (ks+1 .eq. kte) then
            sa = sk
         else
            sa = th_vt(slot_,ks+1,iv)*pool_pr(slot_,ks+1,ir)
         endif
         if (ivn .gt. 0) then
            skn = th_vt(slot_,k,ivn)*pool_pr(slot_,k,inn)
            if (ks+1 .eq. kte) then
               san = skn
            else
               san = th_vt(slot_,ks+1,ivn)*pool_pr(slot_,ks+1,inn)
            endif
         endif
         odzq = th_odz(slot_,k)
         orho = th_orho(slot_,k)
         pool_pr(slot_,k,iten) = pool_pr(slot_,k,iten) - sk*odzq*onstep*orho
         if (ivn .gt. 0) pool_pr(slot_,k,inten) = pool_pr(slot_,k,inten) - skn*odzq*onstep*orho
         pool_pr(slot_,k,ir) = MAX(R1, pool_pr(slot_,k,ir) - sk*odzq*DT*onstep)
         if (ivn .gt. 0) pool_pr(slot_,k,inn) = MAX(R2, pool_pr(slot_,k,inn) - skn*odzq*DT*onstep)
         do k = ks, 1, -1
            sk = th_vt(slot_,k,iv)*pool_pr(slot_,k,ir)
            odzq = th_odz(slot_,k)
            orho = th_orho(slot_,k)
            pool_pr(slot_,k,iten) = pool_pr(slot_,k,iten) + (sa-sk)                 &
                                               *odzq*onstep*orho
            pool_pr(slot_,k,ir) = MAX(R1, pool_pr(slot_,k,ir) + (sa-sk) &
                                           *odzq*DT*onstep)
            sa = sk
            if (ivn .gt. 0) then
               skn = th_vt(slot_,k,ivn)*pool_pr(slot_,k,inn)
               pool_pr(slot_,k,inten) = pool_pr(slot_,k,inten) + (san-skn)                 &
                                               *odzq*onstep*orho
               pool_pr(slot_,k,inn) = MAX(R2, pool_pr(slot_,k,inn) + (san-skn) &
                                           *odzq*DT*onstep)
               san = skn
            endif
         enddo
         ! sk: sed(kts) at the start of the sub-step
         if (pool_pr(slot_,1,ir).gt.R1*1000.) &
         pp = pp + sk*DT*onstep
      enddo
      ppt(ip) = pp
      end subroutine th_sediment

      ! calc_effectRad at one level: its statements on the level's values. A level without the species takes the value
      ! calc_effectRad leaves there (cloud 2.49e-6; ice 2.49e-6 or 4.99e-6, snow 4.99e-6 or 9.99e-6, by the column's has_q*);
      ! after the caller's bounds (ice at least 4.99e-6, snow at least 9.99e-6) both give the same number, so the column flags
      ! are not needed: ice 4.99e-6 and snow 9.99e-6 here.
      subroutine th_effect_rad(t, p, qv, qc, qi, ni1, qs, Nt_c, re_qc, re_qi, re_qs)
      !$acc routine seq
      REAL, INTENT(IN) :: t, p, qv, qc, qi, ni1, qs, Nt_c
      REAL, INTENT(OUT) :: re_qc, re_qi, re_qs
      REAL:: rho, rc, nc, ri, ni, rs
      REAL:: smo2, smob, smoc
      REAL:: tc0, loga_, a_, b_
      DOUBLE PRECISION:: lamc, lami
      INTEGER:: inu_c
      real, dimension(15), parameter:: g_ratio = (/24,60,120,210,336,   &
     &                504,720,990,1320,1716,2184,2730,3360,4080,4896/)
      rho = 0.622*p/(R*t*(qv+0.622))
      rc = MAX(R1, qc*rho)
      nc = Nt_c
      ri = MAX(R1, qi*rho)
      ni = MAX(R2, ni1*rho)
      rs = MAX(R1, qs*rho)
      re_qc = 2.49E-6
      if (.not. (rc.le.R1 .or. nc.le.R2)) then
         if (nc.lt.100) then
            inu_c = 15
         elseif (nc.gt.1.E10) then
            inu_c = 2
         else
            inu_c = MIN(15, NINT(1000.E6/nc) + 2)
         endif
         lamc = (nc*am_r*g_ratio(inu_c)/rc)**obmr
         re_qc = MAX(2.51E-6, MIN(SNGL(0.5D0 * DBLE(3.+inu_c)/lamc), 50.E-6))
      endif
      re_qi = 4.99E-6
      if (.not. (ri.le.R1 .or. ni.le.R2)) then
         lami = (am_i*cig(2)*oig1*ni/ri)**obmi
         re_qi = MAX(2.51E-6, MIN(SNGL(0.5D0 * DBLE(3.+mu_i)/lami), 125.E-6))
      endif
      re_qs = 9.99E-6
      if (.not. (rs.le.R1)) then
         tc0 = MIN(-0.1, t-273.15)
         smob = rs*oams
         if (bm_s.gt.(2.0-1.e-3) .and. bm_s.lt.(2.0+1.e-3)) then
            smo2 = smob
         else
            loga_ = sa(1) + sa(2)*tc0 + sa(3)*bm_s &
     &         + sa(4)*tc0*bm_s + sa(5)*tc0*tc0 &
     &         + sa(6)*bm_s*bm_s + sa(7)*tc0*tc0*bm_s &
     &         + sa(8)*tc0*bm_s*bm_s + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*bm_s*bm_s*bm_s
            a_ = 10.0**loga_
            b_ = sb(1) + sb(2)*tc0 + sb(3)*bm_s &
     &         + sb(4)*tc0*bm_s + sb(5)*tc0*tc0 &
     &         + sb(6)*bm_s*bm_s + sb(7)*tc0*tc0*bm_s &
     &         + sb(8)*tc0*bm_s*bm_s + sb(9)*tc0*tc0*tc0 &
     &         + sb(10)*bm_s*bm_s*bm_s
            smo2 = (smob/a_)**(1./b_)
         endif
         loga_ = sa(1) + sa(2)*tc0 + sa(3)*cse(1) &
     &         + sa(4)*tc0*cse(1) + sa(5)*tc0*tc0 &
     &         + sa(6)*cse(1)*cse(1) + sa(7)*tc0*tc0*cse(1) &
     &         + sa(8)*tc0*cse(1)*cse(1) + sa(9)*tc0*tc0*tc0 &
     &         + sa(10)*cse(1)*cse(1)*cse(1)
         a_ = 10.0**loga_
         b_ = sb(1)+ sb(2)*tc0 + sb(3)*cse(1) + sb(4)*tc0*cse(1) &
     &        + sb(5)*tc0*tc0 + sb(6)*cse(1)*cse(1) &
     &        + sb(7)*tc0*tc0*cse(1) + sb(8)*tc0*cse(1)*cse(1) &
     &        + sb(9)*tc0*tc0*tc0 + sb(10)*cse(1)*cse(1)*cse(1)
         smoc = a_ * smo2**b_
         re_qs = MAX(5.01E-6, MIN(0.5*(smoc/smob), 999.E-6))
      endif
      end subroutine th_effect_rad
end module lean_thompson
